-- 0 rot (verworfen). Blindloeser: {"geloest": 8, "abweichend": [], "bestanden": true}.
-- Vorschau: docs/reihe1/A/bauformen/WZ-5.json. Aendert sich der Steckbrief, steigt die Version (Trigger); die
-- Instanzen tragen die neue Version, die alten bleiben fuer die Historie. Der Steckbrief enthaelt den Hash des
-- Generators: aendert sich der Generator, steigt die Version ebenfalls.
--
-- Pruefabfrage: select count(*) from tasks t join bauformen b on b.id = t.bauform_id
--                where b.schluessel = 'WZ-5' and t.bauform_version = b.version;   → 8
do $$ begin perform set_config('edvance.bauform_export', '1', true); end $$;
insert into public.bauformen (schluessel, skill_key, kernidee_key, format, rollen, steckbrief, generator_pfad, status,
                              pruefprotokoll, blindloeser, verdacht)
values ('WZ-5', 'gleichung_quadr_wurzel', 'gleichung_quadr_wurzel:K1', 'mc', '{uebung}'::text[],
        '{"text": "Welche Lösungen hat x² = {c}?", "stufen": {"4": "x² = c, c keine Quadratzahl von 2 bis 60"}, "fehlbilder": [{"key": "qf_nur_positive_loesung", "regel": "nur √c", "gilt_fuer_stufen": [4], "rueckmeldung": "Auch −√c ins Quadrat ergibt c. Gibt es eine zweite Lösung?"}, {"key": "qf_wurzel_als_haelfte", "regel": "±c/2", "gilt_fuer_stufen": [4], "rueckmeldung": "Die Wurzel ist nicht die Hälfte. Prüf: Ergibt (c/2)² wirklich c?"}, {"key": "qf_quadriert_statt_wurzel", "regel": "±c²", "gilt_fuer_stufen": [4], "rueckmeldung": "Um x² rückgängig zu machen, zieht man die Wurzel, man quadriert nicht noch einmal."}], "hinweise": ["Ist {c} eine Quadratzahl?", "Wenn nicht, bleibt die Wurzel als Zahl stehen.", "Denk daran: Auch eine negative Zahl ins Quadrat ist positiv."], "loesungsweg": [], "warum": null, "kontext": null, "figur": null, "zeit_sek": 45, "kann_entfallen": false, "generator_hash": "4f122df713d3"}'::jsonb, 'scripts/bauformen/bauformen/wz_5.py', 'zur_pruefung',
        '{"gruen": 8, "rot": 0, "rot_anteil": 0.0, "gruende": {}, "verdacht": null, "lauf_am": "20261028152744"}'::jsonb, '{"geloest": 8, "abweichend": [], "anteil": 0.0, "bestanden": true, "antworten": {"1": "C", "2": "B", "3": "A", "4": "A", "5": "D", "6": "C", "7": "C", "8": "C"}}'::jsonb, null)
on conflict (schluessel) do update
   set skill_key = excluded.skill_key, kernidee_key = excluded.kernidee_key, format = excluded.format,
       rollen = excluded.rollen, steckbrief = excluded.steckbrief, generator_pfad = excluded.generator_pfad,
       pruefprotokoll = excluded.pruefprotokoll, blindloeser = excluded.blindloeser, verdacht = excluded.verdacht,
       -- Lenas Entscheidung bleibt, solange sich nichts aendert; eine neue Version oeffnet der Trigger.
       status = case when excluded.verdacht is not null then 'entwurf'
                     when bauformen.status = 'entwurf' then 'zur_pruefung'
                     else bauformen.status end;

do $$ begin perform set_config('edvance.hinweis_status', 'setzen', true); end $$;
